'use strict';
const assert=require('assert');const style=require('../../system-master/book-system/governing-style-profile-core.js');
function inputs(over={}){return Object.assign({governing_brief_ref:'BRIEF-1:1',canon_manifest_ref:'CANON-1:1',protected_language_refs:['TERMSET-1'],author_decision_refs:['DEC-1']},over);}
function ctx(over={}){return Object.assign({book_project_id:'BOOK-PROJECT-001',expected_predecessor_profile_ref:null,governing_inputs:inputs()},over);}
function spec(over={}){return Object.assign({profile_id:'STYLE-1',version:'1',book_project_id:'BOOK-PROJECT-001',predecessor_profile_ref:null,language:'en',locale:'en-US',external_style_guide_refs:['CMOS-18'],spelling_usage_terminology:{serial_comma:true,spelling:'US'},protected_term_refs:['TERMSET-1'],exceptions:[],standing:'CURRENT',creation_evidence_refs:['EVID-STYLE-1'],governing_inputs:inputs()},over);}
const tests=[];const t=(id,name,fn)=>tests.push({id,name,fn});
t('Q077','valid versioned profile',()=>{const p=style.createStyleProfile(spec(),ctx());assert.strictEqual(p.version,'1');assert.strictEqual(style.assessCurrentness(p,ctx()).current,true);});
t('Q078','stale predecessor denied',()=>assert.throws(()=>style.createStyleProfile(spec({predecessor_profile_ref:'STYLE-0:1'}),ctx()),e=>e.code==='STYLE_PROFILE_PREDECESSOR_STALE'));
t('Q079','wrong Book profile denied',()=>assert.throws(()=>style.createStyleProfile(spec({book_project_id:'BOOK-OTHER'}),ctx()),e=>e.code==='STYLE_PROFILE_BOOK_MISMATCH'));
t('Q080','invalid governing refs denied',()=>assert.throws(()=>style.createStyleProfile(spec({governing_inputs:inputs({governing_brief_ref:''})}),ctx())));
t('Q081','invalidated profile cannot be provider-current',()=>{const p=style.createStyleProfile(spec(),ctx());p.standing='INVALIDATED';assert.throws(()=>style.projectForProvider(p,ctx()),e=>e.code==='STYLE_PROFILE_NOT_CURRENT');});
t('Q082','style runtime exposes no canonical parent mutation authority',()=>{const p=style.createStyleProfile(spec(),ctx());const projection=style.projectForProvider(p,ctx());assert.strictEqual(projection.canonical_effect_allowed,false);assert.strictEqual(projection.parent_mutation_allowed,false);assert.strictEqual(typeof style.setActiveParentProfile,'undefined');});
t('Q083','provider projection cannot mutate governing profile',()=>{const p=style.createStyleProfile(spec(),ctx());const projection=style.projectForProvider(p,ctx());assert.strictEqual(Object.isFrozen(projection),true);assert.strictEqual(Object.isFrozen(projection.external_style_guide_refs),true);assert.throws(()=>{projection.language='fr';},TypeError);assert.strictEqual(p.language,'en');});
t('Q084','changed invalidation inputs force re-adjudication',()=>{const p=style.createStyleProfile(spec(),ctx());const changed=ctx({governing_inputs:inputs({canon_manifest_ref:'CANON-2:1'})});const s=style.assessCurrentness(p,changed);assert.strictEqual(s.current,false);assert.strictEqual(s.reason,'GOVERNING_INPUTS_CHANGED');});
let passed=0;for(const x of tests){try{x.fn();passed++;console.log(`PASS ${x.id} ${x.name}`);}catch(e){console.error(`FAIL ${x.id} ${x.name}: ${e.stack||e}`);process.exitCode=1;}}console.log(JSON.stringify({qualification:'BOOK-RECONSTRUCTION-B00-F4-STYLE',required:8,observed:tests.length,passed,failed:tests.length-passed,status:passed===8?'PASS':'FAIL'}));if(passed!==8||tests.length!==8)process.exit(1);
